import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from Simple Icons (CC0) "planetscale".
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "light"
  },
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml",
    "theme": "dark"
  }
];

import {
  accountRouter,
  array,
  decodeJson,
  defineApp,
  defineProvider,
  oauth2,
  object,
  router,
  secrets,
  string,
  withApprovals,
} from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";


const planetscale = defineProvider({
  name: "PlanetScale",
  hosts: ["api.planetscale.com", "app.planetscale.com", "auth.planetscale.com"],
  auth: {
    token: secrets({
      label: "Service token",
      fields: object({
        // Sent verbatim as the Authorization header.
        token: string({ minLength: 3 }),
      }),
    }),
    oauth2: oauth2({
      discover: "https://api.planetscale.com",
      scopes: [
        "read_user",
        "read_organization",
        "write_organization",
        "read_databases",
        "write_databases",
        "organization:create_databases",
        "organization:delete_databases",
        "organization:read_databases",
        "organization:write_databases",
        "organization:read_branches",
        "organization:write_branches",
        "organization:delete_branches",
        "organization:read_deploy_requests",
        "organization:write_deploy_requests",
        "organization:approve_deploy_requests",
        "organization:deploy_deploy_requests",
        "organization:read_comments",
        "organization:write_comments",
        "organization:read_backups",
        "organization:write_backups",
        "organization:delete_backups",
        "organization:restore_backups",
        "organization:manage_passwords",
        "organization:manage_read_only_passwords",
        "organization:read_members",
        "organization:read_workflows",
        "organization:write_workflows",
        "organization:read_audit_logs",
      ],
    }),
  },
  async health({ account, fetch, signal }) {
    const authorization =
      account.method === "oauth2" ? `Bearer ${account.fields.access_token}` : account.fields.token;
    const response = await fetch("https://api.planetscale.com/v1/organizations?per_page=1", {
      signal,
      headers: { Authorization: authorization, Accept: "application/json" },
    });
    const list = await decodeJson(
      response,
      object({ data: array(object({ id: string(), name: string() })) }),
    );
    const organization = list.data[0];
    if (!organization) throw new Error("PlanetScale credential has access to no organizations");
    return { accountInfo: { externalId: organization.id, username: organization.name } };
  },
});

export default defineApp(
  { user: { accounts: { planetscale: planetscale.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      await accountRouter(
        user?.accounts.planetscale ?? [],
        (account) =>
          withApprovals(liveOpenapiRouter({ ...options, cache, fetch, signal, account }), (tool) =>
            tool.kind === "mutation" ? always() : undefined,
          ),
        { signal },
      ),
      {
        title: "PlanetScale",
        description:
          "PlanetScale organizations, databases, branches, deploy requests, backups, passwords, workflows and Insights.",
        icons,
      },
    ),
  }),
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

// The document declares only oauth2 globally. Service tokens go in the Authorization header as
// "<service token id>:<service token>", so the global security is removed and replaced by a fallback accepting either.
export const options = {
  source: { url: "https://planetscale.com/docs/openapi.yaml" },
  allowedOrigin: "https://api.planetscale.com",
  securitySchemes: {
    oauth2: {
      type: "oauth2",
      flows: {
        authorizationCode: {
          authorizationUrl: "https://app.planetscale.com/oauth/authorize",
          tokenUrl: "https://auth.planetscale.com/oauth/token",
          scopes: {},
        },
      },
    },
    serviceToken: { type: "apiKey", name: "Authorization", in: "header" },
  },
  methods: { token: [{ scheme: "serviceToken", field: "token", part: "value", prefix: "" }] },
  oauth: ["oauth2"],
  patches: [{ op: "remove", path: "/security" }],
  fallbackSecurity: [{ oauth2: [] as string[] }, { serviceToken: [] as string[] }] as { [x: string]: string[] }[],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/planetscale",
  "description": "PlanetScale organizations, databases, branches, deploy requests, backups, passwords, workflows and Insights through the PlanetScale API.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "PlanetScale"
  },
  "dependencies": {
    "apps": "0.0.1-beta.100"
  }
}
